<?php
declare(strict_types=1);
namespace Gda\AdminGlobal\Controllers;
use Gda\AdminGlobal\Repositories\GlobalAdministrationRepository;use Gda\AdminGlobal\Repositories\GlobalAuditRepository;use Gda\AdminGlobal\Repositories\GlobalUserRepository;use Gda\AdminGlobal\Services\DiagnosticService;use Gda\AdminGlobal\Services\GlobalActivationService;use Gda\AdminGlobal\Services\GlobalAuthService;use Gda\AdminGlobal\Services\GlobalUpdateService;use Gda\AdminGlobal\Views\GlobalView;use Gda\Core\Security\CsrfService;

final class GlobalAdminController{
 public function __construct(private GlobalView $view,private GlobalUserRepository $users,private GlobalAdministrationRepository $admin,private GlobalAuditRepository $audit,private CsrfService $csrf,private string $activationToken,private string $root){}
 private function verifyCsrf():void{if(!$this->csrf->verify($_POST['csrf']??null)){http_response_code(419);exit('Sessão expirada.');}}
 private function redirect(string $path):never{header('Location: '.global_url($path));exit;}
 private function flash(string $type,string $message):void{$_SESSION['global_flash'][]=compact('type','message');}
 public function login():void{if(($_SESSION['auth_scope']??null)==='global')$this->redirect('/dashboard');$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){$this->verifyCsrf();$auth=new GlobalAuthService($this->users,$this->audit);if($auth->attempt((string)($_POST['email']??''),(string)($_POST['password']??'')))$this->redirect('/dashboard');$error='Credenciais globais inválidas.';}$this->view->render('login',['title'=>'Login global','error'=>$error]);}
 public function activate():void{$service=new GlobalActivationService($this->users,$this->audit,$this->activationToken);if(!$service->available()){http_response_code(404);exit('Página não encontrada.');}$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){$this->verifyCsrf();try{$service->activate((string)($_POST['activation_token']??''),trim((string)($_POST['name']??'')),trim((string)($_POST['email']??'')),(string)($_POST['password']??''));$this->flash('success','Administração Global ativada.');$this->redirect('/login');}catch(\Throwable $e){$error='Não foi possível concluir a ativação. Verifique os dados e o token.';}}$this->view->render('activate',['title'=>'Ativação global','error'=>$error]);}
 public function logout():void{$this->verifyCsrf();(new GlobalAuthService($this->users,$this->audit))->logout();$this->redirect('/login');}
 public function dashboard():void{$last=db()->query("SELECT finished_at FROM app_updates WHERE status='completed' ORDER BY id DESC LIMIT 1")->fetchColumn();$this->view->render('dashboard',['title'=>'Dashboard global','metrics'=>$this->admin->dashboard(),'schemaVersion'=>$this->admin->schemaVersion(),'lastUpdate'=>$last,'activities'=>$this->audit->recent(10)]);}
 public function clients():void{$this->view->render('clients',['title'=>'Clientes','companies'=>$this->admin->companies()]);}
 public function client(int $id):void{$company=$this->admin->company($id);if(!$company){http_response_code(404);exit('Cliente não encontrado.');}$this->view->render('client-detail',['title'=>$company['name'],'company'=>$company]);}
 public function status(int $id,string $status):void{$this->verifyCsrf();$company=$this->admin->company($id);if(!$company){http_response_code(404);exit('Cliente não encontrado.');}$this->admin->setCompanyStatus($id,$status);$this->audit->record($status==='active'?'company_activated':'company_deactivated',(int)$_SESSION['user_id'],'company',$id,['status'=>$status]);$this->flash('success','Status do ambiente atualizado sem remover dados.');$this->redirect('/clientes');}
 public function validateEnvironment(int $id):void{$this->verifyCsrf();$company=$this->admin->company($id);if(!$company){http_response_code(404);exit('Cliente não encontrado.');}$valid=!empty($company['users'])&&count($company['cycles'])>=0;$this->audit->record('company_environment_validated',(int)$_SESSION['user_id'],'company',$id,['result'=>$valid?'valid':'attention']);$this->flash($valid?'success':'error',$valid?'Ambiente validado.':'Ambiente requer atenção.');$this->redirect('/clientes/'.$id);}
 public function cycles():void{$this->view->render('cycles',['title'=>'Caixas','cycles'=>$this->admin->cycles()]);}
 public function activities():void{$this->view->render('activities',['title'=>'Atividades globais','activities'=>$this->audit->recent(300)]);}
 public function diagnostics():void{$this->audit->record('global_diagnostics_viewed',(int)$_SESSION['user_id']);$this->view->render('diagnostics',['title'=>'Diagnóstico','report'=>(new DiagnosticService(db(),$this->root))->report()]);}
 public function settings():void{$allowed=['module_name','maintenance_mode','update_policy','structural_limit'];$rows=$this->admin->globalSettings();$editable=['module_name'=>'GDA Caixas','maintenance_mode'=>'off','update_policy'=>'manual','structural_limit'=>'default'];foreach($rows as$r)if(array_key_exists($r['setting_key'],$editable))$editable[$r['setting_key']]=$r['setting_value'];if($_SERVER['REQUEST_METHOD']==='POST'){$this->verifyCsrf();$values=[];foreach($allowed as$key)$values[$key]=mb_substr(trim((string)($_POST[$key]??'')),0,255);$this->admin->saveSettings($values,(int)$_SESSION['user_id']);$this->audit->record('global_settings_changed',(int)$_SESSION['user_id'],'settings',null,['changed_keys'=>$allowed]);$this->flash('success','Configurações globais atualizadas.');$this->redirect('/configuracoes');}$this->view->render('settings',['title'=>'Configurações globais','editable'=>$editable]);}
 public function updates():void{$service=new GlobalUpdateService($this->audit);if($_SERVER['REQUEST_METHOD']==='POST'){$this->verifyCsrf();try{$result=$service->install($_FILES['update_package']??[],(int)$_SESSION['user_id']);$this->flash('success','Atualização concluída em v'.($result['final_version']??'').'. Migrações executadas: '.count($result['migrations']??[]).'.');}catch(\Throwable $e){$this->flash('error',$e->getMessage());}$this->redirect('/atualizacoes');}$this->view->render('updates',['title'=>'Atualizações','history'=>$service->history()]);}
}
